BEGIN;
DO $$ BEGIN CREATE TYPE custody_model AS ENUM ('A','B'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE epr_namespace AS ENUM ('installation','credential','shape'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
CREATE TABLE custody_rows (id uuid PRIMARY KEY,tenant_id uuid NOT NULL,project_id uuid NOT NULL,namespace epr_namespace NOT NULL,credential_class text NOT NULL,custody_model custody_model NOT NULL,key_locator text,metadata jsonb NOT NULL DEFAULT '{}',minted_by_principal_id uuid NOT NULL REFERENCES principals(id),minted_by_actor_id uuid REFERENCES actors(id),granting_event_id uuid REFERENCES events(id),issued_at timestamptz NOT NULL DEFAULT clock_timestamp(),rotated_at timestamptz,expires_at timestamptz,revoked_at timestamptz,terminal_at timestamptz,retention_policy text NOT NULL,FOREIGN KEY(tenant_id,project_id) REFERENCES projects(tenant_id,id),CHECK(custody_model<>'B' OR key_locator IS NOT NULL),CHECK(custody_model<>'A' OR key_locator IS NULL));
CREATE TABLE minted_references (reference text PRIMARY KEY CHECK(reference~'^epr:(installation|credential|shape):[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'),custody_row_id uuid NOT NULL UNIQUE REFERENCES custody_rows(id),tenant_id uuid NOT NULL,project_id uuid NOT NULL,namespace epr_namespace NOT NULL,minted_at timestamptz NOT NULL DEFAULT clock_timestamp(),FOREIGN KEY(tenant_id,project_id) REFERENCES projects(tenant_id,id),CHECK(split_part(reference,':',2)=namespace::text));
CREATE TABLE custody_audit (audit_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,project_id uuid NOT NULL,namespace epr_namespace NOT NULL,credential_class text NOT NULL,action text NOT NULL,outcome text NOT NULL,principal_id uuid NOT NULL,actor_id uuid,accepted_at timestamptz NOT NULL DEFAULT clock_timestamp(),reference text NOT NULL);
CREATE UNIQUE INDEX custody_single_active ON custody_rows(tenant_id,project_id,namespace,credential_class) WHERE revoked_at IS NULL AND terminal_at IS NULL;
CREATE OR REPLACE FUNCTION mint_custody_reference(p_credential_class text,p_namespace epr_namespace,p_model custody_model,p_key_locator text,p_metadata jsonb DEFAULT '{}') RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE principal uuid:=nullif(current_setting('app.principal_id',true),'')::uuid;t uuid;p uuid;g founder_authorities%ROWTYPE;row_id uuid:=gen_random_uuid();ref text;ms bigint; BEGIN IF principal IS NULL THEN RAISE EXCEPTION 'MINT_AUTHORITY_REFUSED' USING ERRCODE='42501';END IF;SELECT * INTO g FROM founder_authorities WHERE principal_id=principal FOR SHARE;IF NOT FOUND OR g.expires_at<=clock_timestamp() OR NOT('custody:mint'=ANY(g.scopes)) THEN RAISE EXCEPTION 'MINT_AUTHORITY_REFUSED' USING ERRCODE='42501';END IF;SELECT tenant_id,project_id INTO t,p FROM project_memberships WHERE principal_id=principal LIMIT 1;IF t IS NULL THEN RAISE EXCEPTION 'TENANT_PROJECT_REFUSED' USING ERRCODE='42501';END IF;IF p_model='B' AND p_key_locator IS NULL THEN RAISE EXCEPTION 'KEY_LOCATOR_REQUIRED';END IF;IF p_model='A' AND p_key_locator IS NOT NULL THEN RAISE EXCEPTION 'KEY_LOCATOR_FORBIDDEN';END IF;ms:=floor(extract(epoch from clock_timestamp())*1000)::bigint;ref:=format('epr:%s:%s-%s-7%s-8%s-%s',p_namespace,substr(to_hex(ms),1,8),substr(to_hex(ms),9),substr(replace(row_id::text,'-',''),1,3),substr(replace(row_id::text,'-',''),18,3),substr(replace(row_id::text,'-',''),21,12));INSERT INTO custody_rows(id,tenant_id,project_id,namespace,credential_class,custody_model,key_locator,metadata,minted_by_principal_id,retention_policy) VALUES(row_id,t,p,p_namespace,p_credential_class,p_model,p_key_locator,p_metadata,principal,'RET-AUDIT-400');INSERT INTO minted_references VALUES(ref,row_id,t,p,p_namespace,clock_timestamp());INSERT INTO custody_audit(tenant_id,project_id,namespace,credential_class,action,outcome,principal_id,reference) VALUES(t,p,p_namespace,p_credential_class,'mint','success',principal,ref);RETURN ref;EXCEPTION WHEN unique_violation THEN RAISE EXCEPTION 'REFERENCE_COLLISION' USING ERRCODE='23505';END $$;
REVOKE ALL ON custody_rows,minted_references,custody_audit FROM PUBLIC,engram_app;REVOKE ALL ON FUNCTION mint_custody_reference(text,epr_namespace,custody_model,text,jsonb) FROM PUBLIC,engram_app;GRANT SELECT ON custody_rows,minted_references TO engram_app;GRANT EXECUTE ON FUNCTION mint_custody_reference(text,epr_namespace,custody_model,text,jsonb) TO engram_maintenance;GRANT SELECT,INSERT,UPDATE,DELETE ON custody_rows,minted_references,custody_audit TO engram_maintenance;
ALTER TABLE custody_rows ENABLE ROW LEVEL SECURITY;ALTER TABLE custody_rows FORCE ROW LEVEL SECURITY;ALTER TABLE minted_references ENABLE ROW LEVEL SECURITY;ALTER TABLE minted_references FORCE ROW LEVEL SECURITY;ALTER TABLE custody_audit ENABLE ROW LEVEL SECURITY;ALTER TABLE custody_audit FORCE ROW LEVEL SECURITY;
CREATE POLICY custody_read ON custody_rows FOR SELECT USING(tenant_id=nullif(current_setting('app.tenant_id',true),'')::uuid);CREATE POLICY reference_read ON minted_references FOR SELECT USING(tenant_id=nullif(current_setting('app.tenant_id',true),'')::uuid);CREATE POLICY audit_read ON custody_audit FOR SELECT USING(tenant_id=nullif(current_setting('app.tenant_id',true),'')::uuid);
COMMIT;
